after.content:
import { readFile } from "node:fs/promises";
import { normalizeFixture } from "../src/normalize.mjs";

const manifest = JSON.parse(await readFile("contracts/fixtures/manifest.json", "utf8"));

for (const fixture of manifest.fixtures) {
  test(`normalizes pinned Pi ${fixture.domain} fixture deterministically`, async () => {
    const path = `contracts/fixtures/${fixture.path}`;
    const first = await normalizeFixture(path);
    const second = await normalizeFixture(path);
    assert.deepEqual(first, second);
    assert.equal(first.schemaVersion, "ji-pi-projection-v1");
    assert.equal(first.fixtureId, fixture.id);
    assert.equal(first.domain, fixture.domain);
    assert.deepEqual(first, JSON.parse(await readFile(`contracts/fixtures/${fixture.expectedPath}`, "utf8")));
  });
}

test("fixture manifest keeps the five Pi vocabularies separate", () => {
  assert.deepEqual(manifest.fixtures.map(({ domain }) => domain).sort(), [
    "agent-loop", "compaction", "protocol", "provider", "session",
  ]);
  assert.equal(new Set(manifest.fixtures.map(({ path }) => path)).size, 5);
});
